/* eslint-disable @typescript-eslint/ban-ts-comment -- .open-next/worker.js exists only after a
   build, so @ts-expect-error would fail once it does. */
/**
 * Worker entry: the OpenNext app (fetch) plus a daily cron job (wrangler.jsonc → triggers).
 * Built by `opennextjs-cloudflare build` first, then bundled by wrangler with this file as main.
 */
import { drizzle } from "drizzle-orm/d1";
// @ts-ignore -- generated by `opennextjs-cloudflare build` (missing before the first build)
import handler from "./.open-next/worker.js";
import * as schema from "./src/db/schema";
import { purgeExpiredRejected } from "./src/lib/recruitment/retention";

export default {
  fetch: handler.fetch,
  async scheduled(_controller, env, ctx) {
    ctx.waitUntil(
      purgeExpiredRejected(drizzle(env.DB, { schema })).then(
        (n) => console.log(`[retention] deleted ${n} expired rejected application(s)`),
        (err) => console.error("[retention] failed", err),
      ),
    );
  },
} satisfies ExportedHandler<CloudflareEnv>;

// @ts-ignore -- generated by `opennextjs-cloudflare build` (missing before the first build)
export { BucketCachePurge, DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";
